Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cstring>
#include <queue>
#include <algorithm>
using namespace std;

const int INF = 1 << 29;
const int MAXN = 500;

struct edge { int a, b, cap, flow; };
vector<int> g[MAXN];
vector<edge> e;
int d[MAXN], ptr[MAXN];
int n, t, sx, sy, temp[11][11];
bool m[11][11];

void add_edge(int a, int b, int cap) {
    edge e1 = {a, b, cap, 0};
    edge e2 = {b, a, 0, 0};
    g[a].push_back((int)e.size());
    e.push_back(e1);
    g[b].push_back((int)e.size());
    e.push_back(e2);
}

bool bfs() {
    queue<int> q;
    q.push(0);
    memset(d, -1, (n * n * 2 + 2) * sizeof(d[0]));
    d[0] = 0;
    while (!q.empty() && d[n * n * 2 + 1] == -1) {
        int v = q.front();
        q.pop();
        for (size_t j = 0; j < g[v].size(); ++j) {
            int id = g[v][j], to = e[id].b;
            if (d[to] == -1 && e[id].flow < e[id].cap) {
                q.push(to);
                d[to] = d[v] + 1;
            }
        }
    }
    return d[n * n * 2 + 1] != -1;
}

int dfs(int v, int flow) {
    if (!flow) return 0;
    if (v == n * n * 2 + 1) return flow;
    for (; ptr[v] < (int)g[v].size(); ++ptr[v]) {
        int id = g[v][ptr[v]], to = e[id].b;
        if (d[to] != d[v] + 1) continue;
        int pushed = dfs(to, min(flow, e[id].cap - e[id].flow));
        if (pushed) {
            e[id].flow += pushed;
            e[id ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int flow = 0;
    while (bfs()) {
        memset(ptr, 0, (n * n * 2 + 2) * sizeof(ptr[0]));
        while (int pushed = dfs(0, INF))
            flow += pushed;
    }
    return flow;
}

int way(int x1, int y1, int x2, int y2) {
    queue<pair<int, pair<int, int> > > q;
    q.push(make_pair(0, make_pair(x1, y1)));
    int h[11][11];
    for (int i = 0; i < 11; ++i)
        for (int j = 0; j < 11; ++j)
            h[i][j] = INF;

    int dx[4] = {-1, 0, 1, 0};
    int dy[4] = {0, -1, 0, 1};

    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        h[x][y] = v;

        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + dx[dir], ny = y + dy[dir];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (!m[nx][ny]) continue;
            if (h[nx][ny] <= v + 1) continue;
            bool target = (nx == x2 && ny == y2);
            int lim = temp[nx][ny];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(nx, ny)));
        }
    }
    return h[x2][y2];
}

int main() {
    cin >> n >> t;
    queue<pair<int, pair<int, int> > > q;
    char ch;
    int k = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            temp[i][j] = t;
            if (ch == 'Z') {
                sx = i;
                sy = j;
                m[i][j] = false;
            } else if (ch == 'Y') {
                m[i][j] = false;
            } else {
                m[i][j] = true;
            }
            add_edge(0, k++, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    k = n * n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            add_edge(k++, n * n * 2 + 1, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    q.push(make_pair(0, make_pair(sx, sy)));
    int dx[4] = {-1, 0, 1, 0};
    int dy[4] = {0, -1, 0, 1};
    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        temp[x][y] = v;
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + dx[dir], ny = y + dy[dir];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (v + 1 < temp[nx][ny] && m[nx][ny])
                q.push(make_pair(v + 1, make_pair(nx, ny)));
        }
    }

    k = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int k1 = n * n;
            ++k;
            for (int z = 0; z < n; ++z) {
                for (int w = 0; w < n; ++w) {
                    ++k1;
                    if (m[i][j] && m[z][w] && way(i, j, z, w) <= t)
                        add_edge(k, k1, INF);
                }
            }
        }
    }

    cout << max_flow();
    return 0;
}
